const raw = $input.first()?.json ?? {};
const payload = raw.body && typeof raw.body === 'object' ? raw.body : raw;

function cleanText(value, maxLength) {
  if (typeof value !== 'string') return null;
  const cleaned = value.replace(/\u0000/g, '').replace(/\r\n?/g, '\n').trim();
  return cleaned ? cleaned.slice(0, maxLength) : null;
}

function finiteId(value) {
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return String(value);
  if (typeof value === 'string' && /^[1-9]\d*$/.test(value.trim())) return value.trim();
  return null;
}

const messageType = payload.message_type === 0 || payload.message_type === 'incoming'
  ? 'incoming'
  : payload.message_type === 1 || payload.message_type === 'outgoing'
    ? 'outgoing'
    : 'unknown';
const isPrivate = payload.private === true;
const eventName = cleanText(payload.event, 100);
const eventKind = eventName === 'message_created' && messageType === 'incoming'
  ? 'incoming_customer_message'
  : eventName === 'message_created' && messageType === 'outgoing' && !isPrivate
    ? 'agent_public_message'
    : 'ignored';

return [{
  json: {
    event_kind: eventKind,
    event_name: eventName,
    conversation_id: finiteId(payload.conversation?.id ?? payload.conversation_id),
    message_id: finiteId(payload.id ?? payload.message?.id),
    inbox_id: finiteId(payload.inbox?.id ?? payload.conversation?.inbox_id),
    account_id: finiteId(payload.account?.id ?? payload.account_id),
    channel: cleanText(payload.conversation?.channel ?? payload.channel, 100),
    message: cleanText(payload.content ?? payload.message?.content, 8000),
    sender_name: cleanText(payload.sender?.name, 200),
    sender_email: cleanText(payload.sender?.email, 320)?.toLowerCase() ?? null,
    occurred_at: typeof payload.created_at === 'number'
      ? new Date(payload.created_at * 1000).toISOString()
      : cleanText(payload.created_at, 100),
  },
}];

const ALLOWED_FIELDS = new Set([
  'event_kind', 'event_name', 'conversation_id', 'message_id', 'inbox_id',
  'account_id', 'channel', 'message', 'sender_name', 'sender_email', 'occurred_at',
]);

return $input.all().map((item, index) => {
  const value = item.json ?? {};
  const errors = [];
  for (const key of Object.keys(value)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, code: 'undeclared_property' });
  }
  if (!['incoming_customer_message', 'agent_public_message', 'ignored'].includes(value.event_kind)) {
    errors.push({ field: 'event_kind', code: 'invalid_enum' });
  }
  if (value.event_kind !== 'ignored') {
    if (!value.conversation_id) errors.push({ field: 'conversation_id', code: 'required' });
    if (!value.message_id) errors.push({ field: 'message_id', code: 'required' });
    if (!value.account_id) errors.push({ field: 'account_id', code: 'required' });
    if (!value.message) errors.push({ field: 'message', code: 'required' });
  }
  if (value.sender_email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.sender_email)) {
    errors.push({ field: 'sender_email', code: 'invalid_format' });
  }

  return {
    json: {
      support_event: errors.length === 0 ? value : null,
      validation: { is_valid: errors.length === 0, errors },
    },
    pairedItem: { item: index },
  };
});

const { createHash, randomUUID } = require('crypto');

return $input.all().map((item, index) => {
  const event = item.json.support_event;
  const source = `${event.account_id}|${event.conversation_id}|${event.message_id}|${event.event_kind}`;
  return {
    json: {
      support_event: event,
      correlation_id: randomUUID(),
      idempotency_key: createHash('sha256').update(source, 'utf8').digest('hex'),
    },
    pairedItem: { item: index },
  };
});

const claim = $('Prepare Idempotency Claim').first().json;
const result = $input.first()?.json ?? {};
const action = result.claim_action === 'claimed' ? 'claimed' : 'duplicate';

return [{
  json: {
    support_event: claim.support_event,
    correlation_id: claim.correlation_id,
    idempotency_key: claim.idempotency_key,
    idempotency: {
      action,
      should_process: action === 'claimed',
    },
  },
}];

const claim = $('Attach Idempotency Result').first().json;
const response = $input.first()?.json ?? {};
const messages = Array.isArray(response.payload) ? response.payload : [];
const currentMessageId = claim.support_event.message_id;

const conversationContext = messages
  .filter((message) => message && message.private !== true && String(message.id ?? '') !== currentMessageId)
  .filter((message) => message.message_type === 0 || message.message_type === 1 || message.message_type === 'incoming' || message.message_type === 'outgoing')
  .slice(-10)
  .map((message) => ({
    role: message.message_type === 1 || message.message_type === 'outgoing' ? 'agent' : 'customer',
    content: typeof message.content === 'string'
      ? message.content.replace(/\u0000/g, '').replace(/\r\n?/g, '\n').trim().slice(0, 2000)
      : '',
  }))
  .filter((message) => message.content);

return [{ json: { support_event: claim.support_event, conversation_context: conversationContext } }];
